package net.officefloor.hq.app.asof;

import org.springframework.boot.transaction.autoconfigure.TransactionManagerCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.support.AbstractPlatformTransactionManager;

/**
 * Allows a nested (savepoint) transaction, so a sheet shown as of a date within another as-of read (see
 * {@link SheetPasts}) is rolled back to its savepoint only, leaving the outer read's sheet as it was.
 */
@Configuration
public class AsOfTransactions {

    @Bean
    TransactionManagerCustomizer<AbstractPlatformTransactionManager> nestedTransactions() {
        return transactions -> transactions.setNestedTransactionAllowed(true);
    }
}
